import {play} from './engine.js';
export const REVIEW_VERSION=1;
export function moveIndex(move,size){return move.x<0||move.y<0?-1:move.y*size+move.x}
export function gtpIndex(text,size){if(String(text).toLowerCase()==='pass')return -1;const m=/^([A-HJ-T])(\d{1,2})$/i.exec(text);if(!m)return null;const x='ABCDEFGHJKLMNOPQRST'.indexOf(m[1].toUpperCase()),y=size-Number(m[2]);return x<size&&y>=0&&y<size?y*size+x:null}
export function legalLine(state,pv=[]){let s=state;const out=[];for(const text of pv){const index=gtpIndex(text,s.size);if(index===null)break;const r=play(s,index);if(!r.ok)break;out.push(r.state);s=r.state}return out}
export function reviewMoment(before,after,analysis,nextAnalysis){const actual=after.moves.at(-1)?.index;const best=analysis.moves.find(m=>play(before,moveIndex(m,before.size)).ok);if(!best)throw new Error('추천 수를 찾지 못했습니다.');const bestIndex=moveIndex(best,before.size),sign=before.toPlay===1?1:-1;const candidate=analysis.moves.find(m=>moveIndex(m,before.size)===actual);const actualScore=candidate?.scoreLead??nextAnalysis?.rootScoreLead;const loss=actual===bestIndex?0:Math.max(0,sign*(best.scoreLead-actualScore));if(!Number.isFinite(loss))throw new Error('분석값이 부족합니다.');return {turn:before.moves.length+1,color:before.toPlay,actual,best:bestIndex,loss,score:analysis.rootScoreLead,blackWinRate:analysis.rootWinRate,visits:analysis.rootVisits,pv:best.pv||[],candidates:analysis.moves.slice(0,3).map(m=>({index:moveIndex(m,before.size),score:m.scoreLead,blackWinRate:m.winRate,visits:m.visits})),label:loss>=5?'큰 실수 후보':loss>=2?'아쉬운 수 후보':'무난한 수',version:REVIEW_VERSION}}
export function recordSignature(rec){return JSON.stringify([rec.settings.size,rec.settings.handicap,rec.settings.komi,rec.moves.map(m=>typeof m==='number'?m:m.index)])}
